using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Text;
internal static partial class NativeBackground {
 public static bool WholeEnabled {get{return File.Exists(Path.Combine(Engine.Store,"whole-background.enabled"));}set{Directory.CreateDirectory(Engine.Store);string path=Path.Combine(Engine.Store,"whole-background.enabled");if(value)File.WriteAllText(path,"1");else if(File.Exists(path))File.Delete(path);}}
 public static bool UniformBackdrop {get{return File.Exists(Path.Combine(Engine.Store,"backdrop-uniform.enabled"));}set{string path=Path.Combine(Engine.Store,"backdrop-uniform.enabled");if(value)File.WriteAllText(path,"1");else if(File.Exists(path))File.Delete(path);}}
 public static int ImageStrength {get{int value;return int.TryParse(File.Exists(Path.Combine(Engine.Store,"background-strength.txt"))?File.ReadAllText(Path.Combine(Engine.Store,"background-strength.txt")):"35",out value)?Math.Max(10,Math.Min(100,value)):35;}set{Directory.CreateDirectory(Engine.Store);File.WriteAllText(Path.Combine(Engine.Store,"background-strength.txt"),Math.Max(10,Math.Min(100,value)).ToString());}}
 sealed class WholeTarget {public long Widget,Table,OldImage;public bool PaintRoot,InputBorder;public byte[] DelegateBytes;public long OriginalDelegate,CloneDelegate;public string File,Name;public Rectangle Bounds;}
 sealed class WholePlan {public List<WholeTarget> Targets=new List<WholeTarget>(),Clear=new List<WholeTarget>(),FillRestore=new List<WholeTarget>(),FillDisable=new List<WholeTarget>(),RowRefresh=new List<WholeTarget>(),DelegateRestore=new List<WholeTarget>(),DelegateApply=new List<WholeTarget>();public string ChatImage;public bool HasWork{get{return Targets.Count+Clear.Count+FillRestore.Count+FillDisable.Count+DelegateRestore.Count+DelegateApply.Count>0;}}}
 static bool AutoFillValue(IntPtr h,long widget){long extra=Pointer(h,Pointer(h,widget+8)+0x58);return extra!=0&&(BitConverter.ToUInt32(Read(h,extra+0x6c,4),0)&16)!=0;}
 static long Pointer(IntPtr h,long a){return BitConverter.ToInt64(Read(h,a,8),0);}
 static string WidgetClass(IntPtr h,long image,long obj){try{long fn=Pointer(h,Pointer(h,obj));var code=Read(h,fn,128);for(int i=0;i<code.Length-7;i++)if(code[i]==0x48&&code[i+1]==0x8d&&(code[i+2]==5||code[i+2]==13)){long meta=fn+i+7+BitConverter.ToInt32(code,i+3);if(meta<image||meta>image+0xc000000)continue;try{long str=Pointer(h,meta+8);var data=Read(h,str,24);int len=BitConverter.ToInt32(data,4);long off=BitConverter.ToInt64(data,16);if(len<1||len>160||off<0||off>65536)continue;string name=Encoding.ASCII.GetString(Read(h,str+off,len));if(name.All(c=>Char.IsLetterOrDigit(c)||c==':'||c=='_'))return name;}catch{}}}catch{}return "?";}
 static Rectangle WidgetRect(IntPtr h,long obj){long d=Pointer(h,obj+0x28);var r=Read(h,d+0x14,16);int x=BitConverter.ToInt32(r,0),y=BitConverter.ToInt32(r,4),w=BitConverter.ToInt32(r,8)-x+1,ht=BitConverter.ToInt32(r,12)-y+1;if(w<0||w>8192||ht<0||ht>8192)throw new IOException("Unexpected widget geometry");return new Rectangle(x,y,w,ht);}
 static IEnumerable<long> WidgetChildren(IntPtr h,long obj){var result=new List<long>();try{long data=Pointer(h,Pointer(h,obj+8)+0x18);var hdr=Read(h,data,16);int begin=BitConverter.ToInt32(hdr,8),end=BitConverter.ToInt32(hdr,12);if(begin<0||end<begin||end-begin>300)return result;for(int i=begin;i<end;i++)result.Add(Pointer(h,data+16+8L*i));}catch{}return result;}
 static Point RootPosition(IntPtr h,long obj,long root){int x=0,y=0;for(int i=0;i<32&&obj!=root;i++){var r=WidgetRect(h,obj);x+=r.X;y+=r.Y;obj=Pointer(h,Pointer(h,obj+8)+0x10);if(obj==0)throw new IOException("Widget detached");}if(obj!=root)throw new IOException("Unexpected widget ancestry");return new Point(x,y);}
 static readonly HashSet<string> WholeClasses=new HashSet<string>{"mmui::ChatSessionList","mmui::MainView","mmui::MainTabBar","mmui::ChatMasterView","mmui::ChatDetailView","mmui::ChatMessagePage","mmui::ChatInputView","mmui::ChatEditView","mmui::XView","mmui::XVBoxView","mmui::XHBoxView"};
 static void CollectSessionFills(IntPtr h,long image,long table,WholePlan plan){try{long parent=Pointer(h,Pointer(h,table+8)+0x10);if(WidgetClass(h,image,parent)!="mmui::ChatSessionList")return;long d=Pointer(h,table+0x28);if((BitConverter.ToUInt32(Read(h,d+8,4),0)&(1<<15))==0)return;foreach(long viewport in WidgetChildren(h,table)){if(WidgetClass(h,image,viewport)!="QWidget")continue;var rect=WidgetRect(h,viewport);if(rect.Width<120||rect.Height<80)continue;foreach(long content in WidgetChildren(h,viewport))foreach(long cell in WidgetChildren(h,content))try{if(WidgetClass(h,image,cell)=="mmui::ChatSessionCell"&&plan.RowRefresh.Count<128)plan.RowRefresh.Add(new WholeTarget{Widget=cell,Table=Pointer(h,cell)});}catch{}foreach(long obj in new[]{viewport}.Concat(WidgetChildren(h,viewport).Where(child=>WidgetClass(h,image,child)=="QWidget"))){if(plan.FillDisable.Count>=12)break;if(AutoFillValue(h,obj)||plan.FillRestore.Any(t=>t.Widget==obj))plan.FillDisable.Add(new WholeTarget{Widget=obj,Table=Pointer(h,obj)});}}}catch{}}
 static string StoreCrop(Bitmap master,Rectangle bounds){using(var crop=new Bitmap(bounds.Width,bounds.Height,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(crop)){g.DrawImage(master,new Rectangle(0,0,bounds.Width,bounds.Height),bounds,GraphicsUnit.Pixel);}using(var data=new MemoryStream()){crop.Save(data,ImageFormat.Bmp);byte[] bytes=data.ToArray();string dir=Path.Combine(Engine.Store,"runtime-cache");Directory.CreateDirectory(dir);string path=Path.Combine(dir,Engine.Hash(bytes)+".bmp");if(!File.Exists(path))File.WriteAllBytes(path,bytes);return path;}}}
 static void PruneRuntimeCache(IEnumerable<string> active){try{string dir=Path.GetFullPath(Path.Combine(Engine.Store,"runtime-cache"))+Path.DirectorySeparatorChar;if(!Directory.Exists(dir))return;var keep=new HashSet<string>(active.Where(p=>p!=null),StringComparer.OrdinalIgnoreCase);var files=new DirectoryInfo(dir).GetFiles().Where(f=>f.Extension==".png"||f.Extension==".bmp").OrderByDescending(f=>f.LastWriteTimeUtc).ToArray();int spare=Math.Max(0,48-keep.Count);foreach(var file in files.Where(f=>!keep.Contains(f.FullName)).Skip(spare))if(file.FullName.StartsWith(dir,StringComparison.OrdinalIgnoreCase))file.Delete();}catch{}}
 static WholePlan BuildWholePlan(IntPtr h,long image,long instance,string source,long previous,bool removing){var plan=new WholePlan();if(previous!=0){try{if(Encoding.ASCII.GetString(Read(h,previous+0xf000,8))=="WXWHOLE1"){int count=BitConverter.ToInt32(Read(h,previous+0xf008,4),0);if(count>=0&&count<=28)for(int i=0;i<count;i++){var row=Read(h,previous+0xf010+i*24,24);long obj=BitConverter.ToInt64(row,0),table=BitConverter.ToInt64(row,8),old=BitConverter.ToInt64(row,16);try{if(old!=0&&Pointer(h,obj)==table&&Pointer(h,obj+0x160)==old)plan.Clear.Add(new WholeTarget{Widget=obj,Table=table,OldImage=old});}catch{}}}}catch{}}
  if(previous!=0)try{if(Encoding.ASCII.GetString(Read(h,previous+0xf400,8))=="WXFILL01"){int n=BitConverter.ToInt32(Read(h,previous+0xf408,4),0);if(n>=0&&n<=12)for(int i=0;i<n;i++){long obj=Pointer(h,previous+0xf410+i*16),table=Pointer(h,previous+0xf418+i*16);try{if(Pointer(h,obj)==table)plan.FillRestore.Add(new WholeTarget{Widget=obj,Table=table});}catch{}}}}catch{}
  if(previous!=0)try{if(Encoding.ASCII.GetString(Read(h,previous+0xf600,8))=="WXCAPT01"){int n=BitConverter.ToInt32(Read(h,previous+0xf608,4),0);if(n<0||n>4)throw new IOException("Invalid caption records");for(int i=0;i<n;i++){long obj=Pointer(h,previous+0xf610+i*24),original=Pointer(h,previous+0xf618+i*24),clone=Pointer(h,previous+0xf620+i*24);if(Pointer(h,obj+0xc0)==clone&&Pointer(h,clone+8)==image+0x1eb1d40)plan.DelegateRestore.Add(new WholeTarget{Widget=obj,OriginalDelegate=original,CloneDelegate=clone});}}}catch(IOException){throw;}catch{}
  if(previous!=0)try{if(Encoding.ASCII.GetString(Read(h,previous+0x10000,8))=="WXROOT01"){int n=BitConverter.ToInt32(Read(h,previous+0x10008,4),0);if(n<0||n>96)throw new Exception("Invalid root records");for(int i=0;i<n;i++){long obj=Pointer(h,previous+0x10010+i*24),original=Pointer(h,previous+0x10018+i*24),clone=Pointer(h,previous+0x10020+i*24);if(Pointer(h,obj+0xc0)==clone)plan.DelegateRestore.Add(new WholeTarget{Widget=obj,OriginalDelegate=original,CloneDelegate=clone});}}}catch{}
  if(removing||!WholeEnabled)return plan;
  long root=instance;for(int i=0;i<32;i++){long parent=Pointer(h,Pointer(h,root+8)+0x10);if(parent==0)break;root=parent;}if(WidgetClass(h,image,root)!="mmui::MainWindow")throw new IOException("未确认主窗口边界，未应用整窗图片。");var rootRect=WidgetRect(h,root);if(rootRect.Width<300||rootRect.Height<200)throw new IOException("主窗口过小。");
  var chat=WidgetRect(h,instance);chat.Location=RootPosition(h,instance,root);
  using(var picture=Image.FromFile(source))using(var master=BackdropStyle.Compose(picture,rootRect.Width,rootRect.Height,chat,100,true)){
   if(chat.X>=0&&chat.Y>=0&&chat.Right<=master.Width&&chat.Bottom<=master.Height)plan.ChatImage=StoreCrop(master,chat);
   var queue=new Queue<long>();var seen=new HashSet<long>();queue.Enqueue(root);while(queue.Count>0&&seen.Count<2200){long obj=queue.Dequeue();if(!seen.Add(obj))continue;string nodeClass=WidgetClass(h,image,obj);if(nodeClass=="mmui::XTableView"){CollectSessionFills(h,image,obj,plan);continue;}if(obj==instance||nodeClass.Contains("ListView"))continue;foreach(long child in WidgetChildren(h,obj))queue.Enqueue(child);try{string cls=nodeClass;if(!WholeClasses.Contains(cls))continue;long table=Pointer(h,obj);if(Pointer(h,table+29*8)!=image+0x13a58d0)continue;long data=Pointer(h,obj+0x28);if((BitConverter.ToUInt32(Read(h,data+8,4),0)&(1<<15))==0)continue;var r=WidgetRect(h,obj);r.Location=RootPosition(h,obj,root);if(r.Width<32||r.Height<24||r.X<0||r.Y<0||r.Right>master.Width||r.Bottom>master.Height)continue;long old=Pointer(h,obj+0x160);if(old!=0&&!plan.Clear.Any(t=>t.Widget==obj&&t.OldImage==old))continue;plan.Targets.Add(new WholeTarget{Widget=obj,Table=table,Name=cls,Bounds=r});}catch{}}
   var rootView=plan.Targets.Where(t=>t.Name=="mmui::MainView").OrderByDescending(t=>(long)t.Bounds.Width*t.Bounds.Height).FirstOrDefault();if(rootView==null)throw new IOException("未确认单层背景主容器。");
   var readability=BackgroundEffects.Load();var inputBorder=InputAppearance.Load();bool friendsMask=false,chatMask=false,inputMask=false;var headerMasks=new List<Rectangle>();
   foreach(var t in plan.Targets.Take(96)){long current=Pointer(h,t.Widget+0xc0);var saved=plan.DelegateRestore.FirstOrDefault(d=>d.Widget==t.Widget);long original=saved==null?current:saved.OriginalDelegate;long callback=Pointer(h,original+8);if(callback!=image+0x40b0c80&&callback!=image+0x1eb1d40&&!(t.Name=="mmui::ChatInputView"&&callback==image+0x1c13680))continue;t.PaintRoot=t.Widget==rootView.Widget;if(t.Name=="mmui::MainTabBar"&&readability.Navigation>0){t.File=BackgroundEffects.Mask(readability.Color,readability.Navigation);t.PaintRoot=true;}else if(t.Bounds.Bottom<=chat.Top+1&&t.Bounds.Height>=20&&t.Bounds.Width>=100&&readability.Header>0&&!headerMasks.Any(r=>r.Contains(t.Bounds))){t.File=BackgroundEffects.Mask(readability.Color,readability.Header);t.PaintRoot=true;headerMasks.Add(t.Bounds);}else if(!friendsMask&&t.Name=="mmui::ChatSessionList"&&readability.Friends>0){t.File=BackgroundEffects.Mask(readability.Color,readability.Friends);t.PaintRoot=true;friendsMask=true;}else if(!inputMask&&t.Name=="mmui::ChatInputView"&&readability.Input>0){t.File=BackgroundEffects.Mask(readability.Color,readability.Input);t.PaintRoot=true;inputMask=true;}else if(!chatMask&&t.Name=="mmui::XVBoxView"&&t.Bounds.Equals(chat)&&readability.Chat>0){t.File=BackgroundEffects.Mask(readability.Color,readability.Chat);t.PaintRoot=true;chatMask=true;}if(t.Name=="mmui::ChatInputView"&&inputBorder.Enabled){t.File=InputAppearance.Prepare(inputBorder);t.PaintRoot=true;t.InputBorder=true;}t.OriginalDelegate=original;t.DelegateBytes=Read(h,original-8,264);plan.DelegateApply.Add(t);}if(!plan.DelegateApply.Any(t=>t.PaintRoot))throw new IOException("未确认单层背景绘制入口。");
   rootView.File=BackgroundEffects.Prepare(source);plan.Targets=plan.DelegateApply.Where(t=>t.PaintRoot).OrderBy(t=>t.Widget==rootView.Widget?0:1).ToList();
  }
  string report=String.Join("\n",plan.Targets.Select(t=>WidgetClass(h,image,t.Widget)+" "+t.Bounds))+"\nViewport fills disabled: "+plan.FillDisable.Count+"\nCaption delegates: "+plan.DelegateApply.Count;File.WriteAllText(Path.Combine(Engine.Store,"whole-background-plan.txt"),report);return plan;
 }
 static void DropSkImage(Code c,long slot,string label){c.Rax(slot);c.Emit(0x48,0x8b,0x00,0x48,0x85,0xc0);c.Emit(0x0f,0x84);int jump=c.B.Count;c.Emit(0,0,0,0);c.Emit(0xf0,0xff,0x48,0x08);c.Jnz(label);c.Emit(0x48,0x89,0xc1,0x48,0x8b,0x00,0xff,0x50,0x08);c.Label(label);int delta=c.B.Count-(jump+4);var bytes=BitConverter.GetBytes(delta);for(int i=0;i<4;i++)c.B[jump+i]=bytes[i];}
 static void WriteWholePlan(byte[] bytes,WholePlan plan,long image,long block){if(plan.DelegateApply.Count>96||plan.Targets.Count>28)throw new IOException("背景模块存储范围超限。");Encoding.ASCII.GetBytes("WXWHOLE1").CopyTo(bytes,0xf000);BitConverter.GetBytes(plan.Targets.Count).CopyTo(bytes,0xf008);if(!plan.HasWork)return;var c=new Code();c.Emit(0x48,0x83,0xec,0x68);
  foreach(var t in plan.DelegateRestore){c.Rax(t.OriginalDelegate);c.Rdx(t.Widget+0xc0);c.Emit(0x48,0x89,0x02);}
  Encoding.ASCII.GetBytes("WXROOT01").CopyTo(bytes,0x10000);BitConverter.GetBytes(plan.DelegateApply.Count).CopyTo(bytes,0x10008);for(int i=0;i<plan.DelegateApply.Count;i++){var t=plan.DelegateApply[i];long clone=block+0x11008+i*0x200;t.CloneDelegate=clone;t.DelegateBytes.CopyTo(bytes,0x11000+i*0x200);BitConverter.GetBytes(t.InputBorder?block+0x3f000:t.PaintRoot?block+0xda00:block+0xd800).CopyTo(bytes,0x11010+i*0x200);BitConverter.GetBytes(t.Widget).CopyTo(bytes,0x10010+i*24);BitConverter.GetBytes(t.OriginalDelegate).CopyTo(bytes,0x10018+i*24);BitConverter.GetBytes(clone).CopyTo(bytes,0x10020+i*24);c.Rax(clone);c.Rdx(t.Widget+0xc0);c.Emit(0x48,0x89,0x02);}
  int index=0;foreach(var target in plan.Clear){long temp=block+0xe000+index*8;c.Rax(target.OldImage);c.Rdx(temp);c.Emit(0x48,0x89,0x02);c.Rax(target.Widget+0x160);c.Emit(0x48,0xc7,0x00,0,0,0,0);DropSkImage(c,temp,"drop_"+index);c.Rcx(target.Widget);c.AbsCall(image+0x5b7260);index++;}
  foreach(var t in plan.FillRestore){c.Rcx(t.Widget);c.Emit(0xba,1,0,0,0);c.AbsCall(image+0x5b6e60);}foreach(var t in plan.FillDisable){c.Rcx(t.Widget);c.Emit(0x31,0xd2);c.AbsCall(image+0x5b6e60);c.Rcx(t.Widget);c.AbsCall(image+0x5b7260);}
  Encoding.ASCII.GetBytes("WXFILL01").CopyTo(bytes,0xf400);BitConverter.GetBytes(plan.FillDisable.Count).CopyTo(bytes,0xf408);for(int i=0;i<plan.FillDisable.Count;i++){BitConverter.GetBytes(plan.FillDisable[i].Widget).CopyTo(bytes,0xf410+i*16);BitConverter.GetBytes(plan.FillDisable[i].Table).CopyTo(bytes,0xf418+i*16);}
  index=0;foreach(var target in plan.Targets){int data=0x6000+index*0x400;long qstring=block+data;BitConverter.GetBytes(qstring+0x20).CopyTo(bytes,data);BitConverter.GetBytes(-1).CopyTo(bytes,data+0x20);BitConverter.GetBytes(target.File.Length).CopyTo(bytes,data+0x24);BitConverter.GetBytes((long)24).CopyTo(bytes,data+0x30);Encoding.Unicode.GetBytes(target.File+"\0").CopyTo(bytes,data+0x38);
   c.Emit(0x48,0x8d,0x4c,0x24,0x20);c.Rdx(qstring);c.Emit(0x45,0x31,0xc0);c.AbsCall(image+ImageFileRva);c.Emit(0x48,0x8d,0x4c,0x24,0x40,0x48,0x8d,0x54,0x24,0x20);c.AbsCall(image+0x70b60);c.Emit(0x48,0x8b,0x44,0x24,0x40);c.Rdx(target.Widget+0x160);c.Emit(0x48,0x89,0x02);c.Rdx(block+0xf010+index*24+16);c.Emit(0x48,0x89,0x02);c.Emit(0x48,0x8d,0x4c,0x24,0x20);c.AbsCall(image+0x4fdbc0);c.Rcx(target.Widget);c.AbsCall(image+0x5b7260);
   BitConverter.GetBytes(target.Widget).CopyTo(bytes,0xf010+index*24);BitConverter.GetBytes(target.Table).CopyTo(bytes,0xf018+index*24);index++;}
  foreach(var row in plan.RowRefresh){c.Rcx(row.Widget);c.AbsCall(image+0x5b7260);}c.Emit(0x48,0x83,0xc4,0x68,0xc3);byte[] code=c.Finish();if(code.Length>0x2000)throw new IOException("主窗口背景计划过大，已停止。");code.CopyTo(bytes,0x4000);
 }
 const long RowColorCall=0x60141ad,RowColorFunction=0x6014740;
 static byte[] RowColorCode(long image,long block){var c=new Code();c.Emit(0x48,0x83,0xec,0x38,0x48,0x89,0x4c,0x24,0x20,0x48,0x89,0x54,0x24,0x28);c.AbsCall(image+RowColorFunction);c.Emit(0x48,0x8b,0x4c,0x24,0x20,0x80,0xb9,0x10,0x02,0,0,1);c.Emit(0x0f,0x84);int selected=c.B.Count;c.Emit(0,0,0,0);c.Emit(0x48,0x8b,0x81,0xe8,0x02,0,0,0x48,0x85,0xc0);c.Emit(0x0f,0x84);int nullParent=c.B.Count;c.Emit(0,0,0,0);c.Emit(0x48,0x8b,0x80,0xc0,0,0,0,0x48,0x85,0xc0);c.Emit(0x0f,0x84);int nullState=c.B.Count;c.Emit(0,0,0,0);c.Emit(0x48,0x8b,0x54,0x24,0x28,0x66,0x0f,0xef,0xc0,0x0f,0x11,0x02);c.Rax(block+0x40);c.Emit(0xff,0x00);c.Label("done");foreach(int at in new[]{selected,nullParent,nullState}){var d=BitConverter.GetBytes(c.B.Count-(at+4));for(int i=0;i<4;i++)c.B[at+i]=d[i];}c.Rax(block+0x44);c.Emit(0xff,0x00);c.Emit(0x48,0x8b,0x44,0x24,0x28,0x48,0x83,0xc4,0x38,0xc3);return c.Finish();}
